import {createServer} from 'node:http';
import {DatabaseSync} from 'node:sqlite';
const db=new DatabaseSync(process.env.APP_DB||'/tmp/hacksandbox-demo.sqlite');
db.exec('CREATE TABLE IF NOT EXISTS ideas(id INTEGER PRIMARY KEY, title TEXT NOT NULL)');
export function add(title){if(typeof title!=='string'||!title.trim()||title.length>160)throw Error('Use a title of 1–160 characters');return db.prepare('INSERT INTO ideas(title) VALUES(?)').run(title.trim());}
export function list(){return db.prepare('SELECT id,title FROM ideas ORDER BY id DESC LIMIT 100').all();}
const html=`<!doctype html><meta name="viewport" content="width=device-width"><title>Idea board</title><style>body{font:18px system-ui;max-width:700px;margin:80px auto;padding:20px;background:#101918;color:#e9fff7}input,button{font:inherit;padding:12px;border-radius:8px}li{padding:12px}</style><h1>Ideas become builds.</h1><p>A real Node + SQLite application inside your sandbox.</p><form><input aria-label="Idea" maxlength="160" required><button>Add idea</button></form><p id="status"></p><ul></ul><script>const endpoint=new URL('api/ideas',document.baseURI);async function load(){const r=await fetch(endpoint);const rows=await r.json();document.querySelector('ul').replaceChildren(...rows.map(x=>{let li=document.createElement('li');li.textContent=x.title;return li}))}document.querySelector('form').onsubmit=async e=>{e.preventDefault();const input=document.querySelector('input');const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:input.value})});document.querySelector('#status').textContent=r.ok?'Saved to SQLite':'Save failed';if(r.ok){input.value='';load()}};load()</script>`;
if(process.env.NODE_ENV!=='test')createServer(async(req,res)=>{try{if(req.url==='/'){res.setHeader('content-type','text/html');res.end(html);return}if(req.url!=='/api/ideas'){res.writeHead(404);res.end();return}res.setHeader('content-type','application/json');if(req.method==='POST'){let body='';for await(const c of req){body+=c;if(body.length>10000)throw Error('Too large')}add(JSON.parse(body).title);res.writeHead(201)}res.end(JSON.stringify(list()))}catch(e){res.writeHead(400);res.end(JSON.stringify({error:e.message}))}}).listen(Number(process.env.PORT||3000),'0.0.0.0',()=>console.log('Idea board ready on port '+(process.env.PORT||3000)));

